'use strict';
const $=s=>document.querySelector(s),params=new URLSearchParams(location.search),pay=params.get('pay')==='1';
let page=0,query='',onlyDebt=params.get('payable')==='1'||pay,requestNumber=0,newId=null;
const format=value=>new Intl.NumberFormat('en-US').format(typeof value==='string'?BigInt(value):value);
function node(tag,text){const element=document.createElement(tag);if(text!==undefined)element.textContent=text;return element;}
async function load(){if(!KashierData.loggedIn()){location.replace('auth.html?next='+encodeURIComponent('suppliers.html'+location.search));return;}const request=++requestNumber;$('#suppliers-status').textContent='خوێندنەوەی دابینکەرەکان…';$('#suppliers-rows').replaceChildren();$('#supplier-previous').disabled=true;$('#supplier-next').disabled=true;try{const [result,summary]=await Promise.all([KashierData.listSuppliers(query,page,onlyDebt),KashierData.getSupplierSummary()]);if(request!==requestNumber)return;$('#payable-total').textContent=format(summary.balance);$('#supplier-debtors-count').textContent=format(summary.debtors);for(const supplier of result.rows){const row=node('tr');for(const value of [supplier.name,supplier.phone||'—',format(supplier.balance)])row.append(node('td',value));const action=node('td'),link=node('a',pay?'پارەدان بە دابینکەر':'حساب و مامەڵەکان');link.className='catalog-link';link.href='supplier.html?id='+supplier.id+(pay?'&action=payment':'');action.append(link);row.append(action);$('#suppliers-rows').append(row);}$('#suppliers-status').textContent=result.rows.length?'':'هیچ دابینکەرێک لەم لیستە نەدۆزرایەوە.';$('#supplier-count').textContent='دابینکەر: '+result.total+' · پەڕە: '+(page+1);$('#supplier-previous').disabled=page===0;$('#supplier-next').disabled=(page+1)*50>=result.total;}catch(e){if(request===requestNumber)$('#suppliers-status').textContent=e.message;}}
$('#only-payable').checked=onlyDebt;$('#suppliers-heading').textContent=pay?'پارەدان بە دابینکەر':onlyDebt?'لیستی قەرزەکان':'دابینکەرەکان';$('#supplier-search').addEventListener('submit',e=>{e.preventDefault();query=$('#supplier-query').value;page=0;load();});$('#only-payable').addEventListener('change',()=>{onlyDebt=$('#only-payable').checked;page=0;load();});$('#supplier-previous').addEventListener('click',()=>{if(page>0){page--;load();}});$('#supplier-next').addEventListener('click',()=>{page++;load();});
$('#new-supplier').addEventListener('click',()=>{newId=crypto.randomUUID();$('#supplier-form').reset();$('#supplier-error').textContent='';$('#supplier-form-dialog').showModal();$('#supplier-name').focus();});$('#supplier-close').addEventListener('click',()=>{if(!$('#supplier-save').disabled)$('#supplier-form-dialog').close();});$('#supplier-form-dialog').addEventListener('cancel',e=>{if($('#supplier-save').disabled)e.preventDefault();});
$('#supplier-form').addEventListener('submit',async e=>{e.preventDefault();if(!$('#supplier-form').reportValidity()||$('#supplier-save').disabled)return;$('#supplier-save').disabled=true;try{const name=$('#supplier-name').value.trim(),phone=$('#supplier-phone').value.trim()||null;if(!name)throw new Error('ناوی دابینکەر بنووسە.');const supplier=await KashierData.createSupplier({name,phone},newId);location.href='supplier.html?id='+supplier.id;}catch(error){$('#supplier-error').textContent=error.message;}finally{$('#supplier-save').disabled=false;}});load();
